DROP TABLE IF EXISTS `movieblogs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `movieblogs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `movie_id` bigint(20) unsigned NOT NULL,
  `tmdb_id` varchar(255) DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `category` text DEFAULT NULL,
  `content` text NOT NULL,
  `image` varchar(255) DEFAULT NULL,
  `director` varchar(255) DEFAULT NULL,
  `release_date` varchar(255) DEFAULT NULL,
  `genre` varchar(255) DEFAULT NULL,
  `profit` varchar(255) DEFAULT NULL,
  `author` varchar(255) DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `movieblogs_movie_id_foreign` (`movie_id`),
  CONSTRAINT `movieblogs_movie_id_foreign` FOREIGN KEY (`movie_id`) REFERENCES `movies` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

