INSERT INTO `movies` VALUES (1,1007757,'Swapped','A small woodland creature and a majestic bird, two natural sworn enemies of the Valley, magically trade places and set off on an adventure of a lifetime to switch back. Their journey soon uncovers a greater threat—one that could endanger not only their species, but the entire valley they call home.','/tHhxWxge06goXU6ZQH1hj7vK8Hd.jpg','2026-05-01',9.0,'glgmAwRDP8s','https://vidlink.pro/movie/1007757','2026-05-16 02:24:58','2026-05-14 02:19:08','2026-05-16 02:24:58',NULL,NULL,0,0,1),(2,3170,'Bambi',NULL,'/wV9e2y4myJ4KMFsyFfWYcUOawyK.jpg',NULL,NULL,NULL,NULL,NULL,'2026-05-14 02:19:08','2026-05-14 02:19:08',NULL,NULL,0,0,1),(3,116711,'Epic',NULL,'/81cSsWzjTfR3cJSqnTiHwy1eyPK.jpg',NULL,NULL,NULL,NULL,NULL,'2026-05-14 02:19:08','2026-05-14 02:19:08',NULL,NULL,0,0,1),(4,896536,'The Legend of Ochi',NULL,'/qYyEelO4JfOwE0Ui5KsrCE0O8UA.jpg',NULL,NULL,NULL,NULL,NULL,'2026-05-14 02:19:08','2026-05-14 02:19:08',NULL,NULL,0,0,1),(5,523366,'Dragon Rider',NULL,'/ucDrOXUrVnr9X3ZmXP2Q68HDIHr.jpg',NULL,NULL,NULL,NULL,NULL,'2026-05-14 02:19:08','2026-05-14 02:19:08',NULL,NULL,0,0,1),(6,10948,'The Fox and the Hound',NULL,'/aC3k6XBaYnulGSkK8263ABjU3Md.jpg',NULL,NULL,NULL,NULL,NULL,'2026-05-14 02:19:08','2026-05-14 02:19:08',NULL,NULL,0,0,1),(7,441130,'Wolfwalkers',NULL,'/vqGiNbdc2sDwsnivMMYzwAoSSu6.jpg',NULL,NULL,NULL,NULL,NULL,'2026-05-14 02:19:08','2026-05-14 02:19:08',NULL,NULL,0,0,1),(8,1226863,'The Super Mario Galaxy Movie','Having thwarted Bowser\'s previous plot to marry Princess Peach, Mario and Luigi now face a fresh threat in Bowser Jr., who is determined to liberate his father from captivity and restore the family legacy. Alongside companions new and old, the brothers travel across the stars to stop the young heir\'s crusade.','/eJGWx219ZcEMVQJhAgMiqo8tYY.jpg','2026-04-01',6.7,'En5QZmL5R1s','https://vidlink.pro/movie/1226863','2026-05-16 02:24:59','2026-05-14 02:19:08','2026-05-16 02:24:59',NULL,NULL,0,0,1),(9,698687,'Transforme